const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const rawText = body.text ?? body.articleText ?? body.content ?? '';
const sourceUrl = String(body.url ?? body.articleUrl ?? '').trim();
const language = String(body.language ?? 'es').trim().toLowerCase();
const audience = String(body.audience ?? 'Creadores de contenido y consultores B2B').trim();
const slideCount = Math.min(Math.max(Number(body.slideCount ?? 8), 5), 10);
const sourceText = typeof rawText === 'string' ? rawText.trim() : '';
if (!sourceUrl && !sourceText) {
  throw new Error('Provide either url or text/articleText/content.');
}
return { json: { sourceUrl, sourceText, language, audience, slideCount, inputMode: sourceUrl ? 'url' : 'text' } };

const html = String($json.data ?? $json.body ?? $json.html ?? '');
const text = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
if (!text) throw new Error('The URL did not return readable article content.');
return { json: { ...$json, sourceText: text.slice(0, 40000) } };

values.content:
You are a senior B2B LinkedIn content strategist. Turn the supplied article or long-form text into a practical LinkedIn carousel that can be copied into Canva.

Return ONLY valid JSON, with no markdown fences, using exactly this shape:
{
  "title": "string",
  "source": "url or text",
  "audience": "string",
  "language": "string",
  "slides": [
    {"number": 1, "headline": "max 60 chars", "body": "max 220 chars", "visual": "short visual direction", "design_notes": "short Canva layout note"}
  ],
  "caption": "LinkedIn post caption with a clear hook and CTA",
  "hashtags": ["#tag"],
  "alt_text": "accessible description of the carousel"
}

Rules:
- Produce exactly {{ $json.slideCount }} slides, not a range. The first slide must be a strong cover and the final slide must be an actionable CTA.
- Return the exact requested values in the `language` and `audience` fields: language must be `{{ $json.language }}` and audience must be `{{ $json.audience }}`. Do not substitute a display name such as English for the language code.
- Extract only claims supported by the source; do not invent facts, statistics, quotes, or citations.
- Use concise, specific B2B language for content creators and B2B consultants.
- One core idea per slide. Make headlines skimmable and body copy ready to paste into a design.
- Use the requested language for all user-facing copy.
- Keep hashtags relevant and limited to 5.

Requested language: {{ $json.language }}
Audience: {{ $json.audience }}
Source mode: {{ $json.inputMode }}
Source URL: {{ $json.sourceUrl || 'Provided text' }}
Source content:
{{ $json.sourceText }}

