const request = $items('Normalize Input', 0, 0)[0]?.json ?? {};
const carousel = $json.carousel;
if (!carousel || !Array.isArray(carousel.slides)) throw new Error('OpenAI response does not contain carousel slides.');
const expectedCount = Number(request.slideCount);
if (expectedCount && carousel.slides.length !== expectedCount) throw new Error(`Expected exactly ${expectedCount} slides but received ${carousel.slides.length}.`);
const expectedLanguage = String(request.language ?? '').trim().toLowerCase();
if (expectedLanguage && String(carousel.language ?? '').trim().toLowerCase() !== expectedLanguage) throw new Error(`Expected language ${expectedLanguage} but received ${carousel.language ?? 'unknown'}.`);
const expectedAudience = String(request.audience ?? '').trim();
if (expectedAudience && String(carousel.audience ?? '').trim() !== expectedAudience) throw new Error('OpenAI response audience does not match the requested audience.');
return { json: $json };
